'use strict';
const $=selector=>document.querySelector(selector);
const state={page:0,limit:50,total:0,request:0,loading:false};
const uuid=value=>/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value||'');
const integer=value=>typeof value==='string'&&/^\d+$/.test(value)?BigInt(value):null;
const money=value=>new Intl.NumberFormat('en-US').format(typeof value==='bigint'?value:BigInt(value||0))+' دینار';
const when=value=>new Intl.DateTimeFormat('ckb-IQ-u-ca-gregory-nu-latn',{timeZone:'Asia/Baghdad',dateStyle:'short',timeStyle:'short'}).format(new Date(value));
function cell(text,cls=''){const e=document.createElement('td');e.textContent=text??'';if(cls)e.className=cls;return e;}
function amount(selector){const raw=$(selector).value.trim();if(!raw)return null;if(!/^\d+$/.test(raw))throw new Error('بڕی قەرز دەبێت ژمارەی تەواو بێت.');const value=BigInt(raw);if(value<0n||value>100000000000000n)throw new Error('بڕی قەرز لە سنووری ڕێگەپێدراو دەرەوەیە.');return value;}
function filters(){const min=amount('#supplier-payables-min'),max=amount('#supplier-payables-max');if(min!==null&&max!==null&&min>max)throw new Error('بڕی کەم نابێت لە بڕی زۆر زیاتر بێت.');return {supplier:$('#supplier-payables-supplier').value.trim(),query:$('#supplier-payables-query').value.trim(),minOutstanding:min===null?null:Number(min),maxOutstanding:max===null?null:Number(max),page:state.page,limit:state.limit};}
function syncUrl(){const p=new URLSearchParams();for(const [key,value] of [['supplier',$('#supplier-payables-supplier').value.trim()],['q',$('#supplier-payables-query').value.trim()],['min',$('#supplier-payables-min').value.trim()],['max',$('#supplier-payables-max').value.trim()]])if(value)p.set(key,value);if(state.page>0)p.set('page',String(state.page+1));history.replaceState(null,'',location.pathname+(p.size?'?'+p.toString():''));}
function restoreUrl(){const p=new URLSearchParams(location.search);for(const [key,selector] of [['supplier','#supplier-payables-supplier'],['q','#supplier-payables-query'],['min','#supplier-payables-min'],['max','#supplier-payables-max']]){const value=p.get(key);if(value!==null)$(selector).value=value.slice(0,100);}const page=Number(p.get('page'));if(Number.isInteger(page)&&page>1)state.page=page-1;}
function validate(data){if(!data||!Array.isArray(data.rows))throw new Error('وەڵامی ناوەندی قەرزەکان تەواو نییە.');const count=integer(String(data.count)),outstanding=integer(data.outstanding),original=integer(data.original_debt),paid=integer(data.allocated_payments),reversed=integer(data.debt_reversed);if(count===null||outstanding===null||original===null||paid===null||reversed===null||original!==paid+reversed+outstanding)throw new Error('کۆی قەرزەکان یەک ناگرێتەوە.');const rows=data.rows.map(row=>{if(!uuid(row.purchase_id)||!uuid(row.supplier_id)||!uuid(row.charge_entry_id)||!/^\d+$/.test(row.receipt_no||'')||typeof row.supplier_name!=='string'||row.supplier_name.length<1||row.supplier_name.length>100||!Number.isFinite(Date.parse(row.created_at)))throw new Error('یەکێک لە پسوولە قەرزدارەکان ناتەواوە.');const total=integer(row.total),initial=integer(row.initial_paid),debt=integer(row.original_debt),later=integer(row.allocated_payments),debtReversed=integer(row.debt_reversed),open=integer(row.outstanding);if([total,initial,debt,later,debtReversed,open].some(v=>v===null)||initial+debt!==total||later+debtReversed+open!==debt||open<=0n)throw new Error('حسابی یەکێک لە پسوولە قەرزدارەکان یەک ناگرێتەوە.');return {...row,totalValue:total,initialValue:initial,debtValue:debt,laterValue:later,reversedValue:debtReversed,outstandingValue:open};});return {count:Number(count),outstanding,original,paid,reversed,rows};}
function render(data){const body=$('#supplier-payables-rows');body.replaceChildren();for(const row of data.rows){const tr=document.createElement('tr');tr.append(cell('P-'+row.receipt_no,'returns-code'),cell(when(row.created_at),'returns-date'));const supplierCell=document.createElement('td');supplierCell.className='payables-supplier';supplierCell.append(document.createTextNode(row.supplier_name));const supplierLink=document.createElement('a');supplierLink.className='payables-supplier-link';supplierLink.href='supplier.html?id='+encodeURIComponent(row.supplier_id);supplierLink.textContent='حسابی دابینکەر';supplierCell.append(supplierLink);tr.append(supplierCell,cell(row.invoice_no||'—','payables-invoice'),cell(money(row.totalValue),'payables-money'),cell(money(row.initialValue),'payables-money'),cell(money(row.debtValue),'payables-money'),cell(money(row.laterValue),'payables-money'),cell(money(row.reversedValue),'payables-money'),cell(money(row.outstandingValue),'payables-money payables-outstanding'));const action=document.createElement('td'),link=document.createElement('a');link.className='payables-action';link.href='purchase-receipt.html?id='+encodeURIComponent(row.purchase_id);link.textContent='پسوولە / پارەدان';action.append(link);tr.append(action);body.append(tr);}$('#supplier-payables-count-total').textContent=new Intl.NumberFormat('en-US').format(data.count);$('#supplier-payables-original').textContent=money(data.original);$('#supplier-payables-paid').textContent=money(data.paid);$('#supplier-payables-reversed').textContent=money(data.reversed);$('#supplier-payables-outstanding').textContent=money(data.outstanding);$('#supplier-payables-empty').hidden=data.rows.length!==0;}
function paging(){const pages=Math.max(1,Math.ceil(state.total/state.limit)),start=state.total?state.page*state.limit+1:0,end=Math.min(state.total,(state.page+1)*state.limit);$('#supplier-payables-count').textContent=state.total?start+'–'+end+' لە '+state.total:'0';$('#supplier-payables-previous').disabled=state.loading||state.page===0;$('#supplier-payables-next').disabled=state.loading||(state.page+1)*state.limit>=state.total;if(!state.total)$('#supplier-payables-count-total').textContent='0';}
function clearRows(){const body=$('#supplier-payables-rows');body.replaceChildren();$('#supplier-payables-empty').hidden=false;for(const selector of ['#supplier-payables-original','#supplier-payables-paid','#supplier-payables-reversed','#supplier-payables-outstanding'])$(selector).textContent='0 دینار';$('#supplier-payables-count-total').textContent='0';}
async function load(){const request=++state.request;if(!KashierData.loggedIn()){location.replace('auth.html?next='+encodeURIComponent('supplier-payables.html'+location.search));return;}let query;try{query=filters();}catch(error){$('#supplier-payables-status').textContent=(globalThis.KashierLocale?.message(error.message)??error.message);return;}state.loading=true;$('#supplier-payables-status').textContent='قەرزە ماوەکان دەخوێندرێنەوە…';$('#supplier-payables-refresh').disabled=true;paging();syncUrl();try{const result=validate(await KashierSupplierPayables.list(query));if(request!==state.request)return;state.total=result.count;const lastPage=Math.max(0,Math.ceil(state.total/state.limit)-1);if(state.page>lastPage){state.page=lastPage;state.loading=false;return load();}if(state.page>0&&result.rows.length===0&&state.total>0)throw new Error('وەڵامی پەڕەکە لە ژمارەی گشتی قەرزەکان جیاوازە؛ نوێکردنەوە بکە.');render(result);$('#supplier-payables-status').textContent=result.rows.length?'':'هیچ پسوولەی قەرزدار بەم فلتەرە نییە.';}catch(error){if(request!==state.request)return;state.total=0;clearRows();$('#supplier-payables-status').textContent=(globalThis.KashierLocale?.message(error.message)??error.message);if(error.status===401)setTimeout(()=>location.replace('auth.html?next='+encodeURIComponent('supplier-payables.html'+location.search)),0);}finally{if(request===state.request){state.loading=false;$('#supplier-payables-refresh').disabled=false;paging();syncUrl();}}}
restoreUrl();$('#supplier-payables-filter').addEventListener('submit',event=>{event.preventDefault();state.page=0;load();});$('#supplier-payables-clear').addEventListener('click',()=>{for(const selector of ['#supplier-payables-supplier','#supplier-payables-query','#supplier-payables-min','#supplier-payables-max'])$(selector).value='';state.page=0;load();});$('#supplier-payables-refresh').addEventListener('click',load);$('#supplier-payables-previous').addEventListener('click',()=>{if(state.page>0){state.page--;load();}});$('#supplier-payables-next').addEventListener('click',()=>{if((state.page+1)*state.limit<state.total){state.page++;load();}});load();
